from dataclasses import dataclass, field
from typing import List, Tuple

@dataclass
class Student:
    name: str
    age: int
    score: float

@dataclass
class StudentRoster:
    names: List[str] = field(default_factory=list)
    ages: List[int] = field(default_factory=list)
    scores: List[float] = field(default_factory=list)

    def add_student(self, name: str, age: int, score: float) -> None:
        self.names.append(name)
        self.ages.append(age)
        self.scores.append(score)

    def average_score(self) -> float:
        return sum(self.scores) / len(self.scores) if self.scores else 0.0

    def top_students(self, n: int) -> List[Tuple[str, int, float]]:
        combined = sorted(zip(self.scores, self.names, self.ages), reverse=True)
        return [(name, age, score) for score, name, age in combined[:n]]
